import struct, zlib

def rec(seq, kind, txid, payload=b""):
    header = struct.pack("<IIBI", len(payload), seq, kind, txid)
    return header + payload + struct.pack("<I", zlib.crc32(header + payload) & 0xffffffff)

def begin(seq, txid): return rec(seq, 1, txid)

def patch(seq, txid, page, off, data):
    return rec(seq, 2, txid, struct.pack("<HHH", page, off, len(data)) + data)

def commit(seq, txid, payloads):
    blob = b"".join(payloads)
    return rec(seq, 3, txid, struct.pack("<II", len(payloads), zlib.crc32(blob) & 0xffffffff))

def commit_bad(seq, txid, count, digest):
    return rec(seq, 3, txid, struct.pack("<II", count, digest))

def abort(seq, txid): return rec(seq, 4, txid)

def patch_payload(page, off, data):
    return struct.pack("<HHH", page, off, len(data)) + data
EOF
